class Solution {
public:
    int countNicePairs(vector<int>& nums) {
        const int MOD = 1000000007;
        unordered_map<long long, long long> freq;
        long long ans = 0;
        for (int x : nums) {
            long long r = 0;
            long long t = x;
            while (t > 0) {
                r = r * 10 + t % 10;
                t /= 10;
            }
            long long d = (long long)x - r;
            ans = (ans + freq[d]) % MOD;
            freq[d]++;
        }
        return (int)ans;
    }
};
